dtsPropsFor.Badge:
/** Visual tone. */
  variant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'success';
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.Button:
/** Visual tone. */
  variant?: 'default' | 'destructive' | 'ghost' | 'link' | 'outline' | 'secondary';
  /** `icon*` sizes render a square control for a lone icon. */
  size?: 'default' | 'lg' | 'sm' | 'xl' | 'xs' | 'icon' | 'icon-lg' | 'icon-sm' | 'icon-xl' | 'icon-xs';
  /** Appends a Spinner and disables the button. */
  loading?: boolean;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  /** Base UI polymorphism — render as another element instead of `<button>`. */
  render?: React.ReactElement;
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.Input:
type?: React.HTMLInputTypeAttribute;
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  /** Switches the control to destructive styling. */
  'aria-invalid'?: boolean;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  className?: string;

dtsPropsFor.Textarea:
placeholder?: string;
  value?: string;
  defaultValue?: string;
  rows?: number;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  'aria-invalid'?: boolean;
  onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
  /** Grows with its content (`field-sizing-content`); min height is 4rem. */
  className?: string;

dtsPropsFor.LinkButton:
href: string;
  /** Defaults to `link`, unlike Button. */
  variant?: 'default' | 'destructive' | 'ghost' | 'link' | 'outline' | 'secondary';
  size?: 'default' | 'lg' | 'sm' | 'xl' | 'xs' | 'icon' | 'icon-lg' | 'icon-sm' | 'icon-xl' | 'icon-xs';
  target?: string;
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.Avatar:
size?: 'default' | 'lg' | 'sm';
  /** Compose with AvatarImage / AvatarFallback / AvatarBadge. */
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.Drawer:
open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Renders a dimmed backdrop and traps focus. Default `true`. */
  modal?: boolean;
  /** Edge the drawer enters from. Default `'down'`. */
  swipeDirection?: 'down' | 'up' | 'left' | 'right';
  snapPoints?: Array<number | string>;
  /** Shows the grab handle inside the popup. */
  showSwipeHandle?: boolean;
  /** Compose with DrawerTrigger / DrawerContent / DrawerHeader / DrawerTitle / DrawerDescription / DrawerFooter / DrawerClose. */
  children?: React.ReactNode;

dtsPropsFor.ScrollArea:
/** Constrain with a `max-h-*`/`h-*` class or the scrollbar never appears. */
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.Tooltip:
open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Compose with TooltipTrigger + TooltipContent, inside a TooltipProvider. */
  children?: React.ReactNode;

dtsPropsFor.Toaster:
position?: 'top-left' | 'top-center' | 'top-right' | 'bottom-left' | 'bottom-center' | 'bottom-right';
  theme?: 'light' | 'dark' | 'system';
  richColors?: boolean;
  closeButton?: boolean;
  expand?: boolean;
  duration?: number;
  /** Mount once near the app root; fire toasts with sonner's `toast()`. */
  className?: string;

dtsPropsFor.StatCard:
/** A lucide-react icon component. */
  icon: React.ComponentType<{ className?: string }>;
  /** Caption under the value, e.g. `'Treinos na semana'`. */
  label: string;
  /** Pre-formatted — the card does no number formatting. */
  value: string;

dtsPropsFor.ConsistencySquare:
/** Filled square — the day's workout was finished. */
  completed: boolean;
  /** Outlined square — the current day, not yet finished. */
  isToday: boolean;
  /** Tinted square — started but not completed. */
  started: boolean;

dtsPropsFor.HeaderBanner:
/** Cover image URL; rendered full-bleed behind a dark gradient. */
  src: string;
  /** Overlaid at the bottom of the banner. */
  children: React.ReactNode;

dtsPropsFor.NavLink:
href: string;
  /** A lucide-react icon component; tinted `text-primary` on the active route. */
  icon: React.ComponentType<{ className?: string }>;

dtsPropsFor.WorkoutDayCard:
workoutDay: {
    name: string;
    weekDay: 'MONDAY' | 'TUESDAY' | 'WEDNESDAY' | 'THURSDAY' | 'FRIDAY' | 'SATURDAY' | 'SUNDAY';
    estimatedDurationInSeconds: number;
    coverImageUrl?: string | null;
    /** Supply this or `exercises` — the card counts whichever is present. */
    exercisesCount?: number;
    exercises?: unknown[];
  };
  /** Slot at the bottom-right, typically a Button. */
  action?: React.ReactNode;
  className?: string;

dtsPropsFor.WorkoutCard:
/** Destination for a training day; rest days render unlinked. */
  href: string;
  workoutDay: {
    name: string;
    weekDay: 'MONDAY' | 'TUESDAY' | 'WEDNESDAY' | 'THURSDAY' | 'FRIDAY' | 'SATURDAY' | 'SUNDAY';
    /** Switches between WorkoutRestCard and WorkoutDayCard. */
    isRest: boolean;
    estimatedDurationInSeconds?: number;
    coverImageUrl?: string | null;
    exercisesCount?: number;
  };
